/** A read-only view of environment variables (e.g. `process.env`). */
export type AgentEnvironment = Record<string, string | undefined>;

/**
 * Returns `true` when Storybook was launched by Claude's preview integration.
 *
 * Claude sets `CLAUDE_AGENT_SDK_VERSION` when it spawns the dev server on the user's behalf. When a
 * generic agent wrapper is also present (`AI_AGENT`), the launch is attributed to that agent
