/** Options accepted by {@link resolveDevCommandOptions}. */
export interface ResolveDevCommandOptions {
  /** Environment variables to read overrides from. Defaults to `process.env`. */
  env?: AgentEnvironment;
}

const MIN_PORT = 1;
const MAX_PORT = 65535;

/** A candidate value is "provided" when it was explicitly set (not merely absent). */
const isProvided = (value: unknown): boolean => value !== undefined && value !== null;

/**
 * Coerces a CLI- or env-provided port into a valid integer, throwing on anything Storybook cannot
 * bind to. Strings are trimmed first so empty/whitespace-only values are rejected, and non-numeric
 * placeholders such as `$PORT` (an un-substituted shell variable) are treated as invalid rather
 * than silently interpolated.
 */
const coercePort = (value: string | number): number => {
  let numeric: number;

  if (typeof value === 'number') {
    numeric = value;
  } else {
    const trimmed = value.trim();
    // `Number('')` is `0`, so empty/whitespace-only strings must be rejected explicitly.
    numeric = trimmed === '' ? Number.NaN : Number(trimmed);
  }

  if (!Number.isInteger(numeric) || numeric < MIN_PORT || numeric > MAX_PORT) {
    const received = typeof value === 'number' ? `${value}` : `"${value}"`;
    throw new Error(
      `Port must be a valid number from 1 to 65535, received ${received}. Storybook cannot start at port ${received}.`
    );
  }

  return numeric;
};

/**
 * Resolves the final set of dev-server options from CLI flags and the environment.
 *
 * Environment variables take precedence over CLI values (matching Storybook's `getEnvConfig`
 * behavior) for `CI`, `SBCONFIG_CONFIG_DIR`, `SBCONFIG_HOSTNAME`, and `SBCONFIG_STATIC_DIR`.
 *
 * Port precedence depends on how Storybook was launched. Normally the explicit `--port` flag wins,
 * falling back to `SBCONFIG_PORT` then `PORT`. When Claude launches the preview, the `PORT` it
 * injects must win so the server lands on the port Claude proxies, and the browser is never opened
 * automatically.
 */
export function resolveDevCommandOptions<T extends Record<string, any>>(
  cliOptions: T,
  { env = process.env }: ResolveDevCommandOptions = {}
): T & { port?: number; open?: boolean } {
  const claudePreview = isClaudePreviewLaunch(env);
  const resolved: Record<string, any> = { ...cliOptions };

  // Truthy environment values override CLI-provided values.
  if (env.CI) {
    resolved.ci = env.CI;
  }
  if (env.SBCONFIG_CONFIG_DIR) {
    resolved.configDir = env.SBCONFIG_CONFIG_DIR;
  }
  if (env.SBCONFIG_HOSTNAME) {
    resolved.host = env.SBCONFIG_HOSTNAME;
  }
  if (env.SBCONFIG_STATIC_DIR) {
    resolved.staticDir = env.SBCONFIG_STATIC_DIR;
  }

  // In Claude preview mode the injected `PORT` wins so Storybook binds to the proxied port.
  const portCandidates = claudePreview
    ? [env.PORT, cliOptions.port, env.SBCONFIG_PORT]
    : [cliOptions.port, env.SBCONFIG_PORT, env.PORT];

  const selectedPort = portCandidates.find(isProvided);
  if (isProvided(selectedPort)) {
    resolved.port = coercePort(selectedPort as string | number);
  }

  // Claude proxies the preview itself, so the dev server must never open a browser.
  if (claudePreview) {
    resolved.open = false;
  }

  return resolved as T & { port?: number; open?: boolean };
}
